CREATE FUNCTION private.financeiro_saldo(_id uuid,_data date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE c public.financeiro_cobrancas; e record; principal bigint; base bigint; multa numeric=0; juros numeric=0; correcao numeric=0; pago_m bigint=0; pago_j bigint=0; pago_c bigint=0; pago_p bigint=0; inicio date; ultima date; dias integer; ab record; BEGIN SELECT * INTO STRICT c FROM public.financeiro_cobrancas WHERE id=_id; base=greatest(0,c.valor_centavos+c.ajuste_centavos); principal=base; inicio=c.vencimento+c.carencia; ultima=inicio; FOR e IN SELECT p.data, sum(a.principal_centavos) pp,sum(a.multa_centavos) pm,sum(a.juros_centavos) pj,sum(a.correcao_centavos) pc FROM public.financeiro_alocacoes a JOIN public.financeiro_pagamentos p ON p.id=a.pagamento_id WHERE a.cobranca_id=_id AND NOT p.estornado AND p.data<=_data GROUP BY p.data ORDER BY p.data LOOP IF e.data>inicio THEN IF multa=0 AND principal>0 THEN multa=round(principal*c.multa_bp::numeric/10000); END IF; juros=juros+principal*c.juros_bp::numeric/10000*greatest(0,e.data-ultima)/30; correcao=correcao+principal*c.correcao_bp::numeric/10000*greatest(0,e.data-ultima)/30; ultima=e.data; END IF; principal=greatest(0,principal-e.pp); pago_p=pago_p+e.pp;pago_m=pago_m+e.pm;pago_j=pago_j+e.pj;pago_c=pago_c+e.pc; END LOOP; IF _data>inicio THEN IF multa=0 AND principal>0 THEN multa=round(principal*c.multa_bp::numeric/10000); END IF; juros=juros+principal*c.juros_bp::numeric/10000*greatest(0,_data-ultima)/30; correcao=correcao+principal*c.correcao_bp::numeric/10000*greatest(0,_data-ultima)/30; END IF; SELECT coalesce(sum(multa_centavos),0) m,coalesce(sum(juros_centavos),0) j,coalesce(sum(correcao_centavos),0) co INTO ab FROM public.financeiro_abatimentos WHERE cobranca_id=_id AND data<=_data; multa=greatest(0,round(multa)-pago_m-ab.m);juros=greatest(0,round(juros)-pago_j-ab.j);correcao=greatest(0,round(correcao)-pago_c-ab.co); dias=greatest(0,_data-c.vencimento); RETURN jsonb_build_object('principal',principal,'multa',multa::bigint,'juros',juros::bigint,'correcao',correcao::bigint,'saldo',CASE WHEN c.cancelada THEN 0 ELSE principal+multa+juros+correcao END,'dias',dias,'pago',pago_p+pago_m+pago_j+pago_c,'status',CASE WHEN c.cancelada THEN 'Cancelada' WHEN principal+multa+juros+correcao=0 THEN 'Paga' WHEN _data>c.vencimento THEN 'Vencida' WHEN pago_p+pago_m+pago_j+pago_c>0 THEN 'Parcialmente paga' ELSE 'Em aberto' END); END; $$;
REVOKE ALL ON FUNCTION private.financeiro_saldo(uuid,date) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION private.financeiro_travar_data(_data date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN PERFORM pg_advisory_xact_lock(81721,(_data-date '2000-01-01')::integer); IF EXISTS(SELECT 1 FROM public.financeiro_caixa WHERE data=_data AND fechado) THEN RAISE EXCEPTION 'O caixa desta data está fechado. Reabra o dia com justificativa.'; END IF; END; $$;
REVOKE ALL ON FUNCTION private.financeiro_travar_data(date) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.financeiro_resumo() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE hoje date=(now() AT TIME ZONE 'America/Sao_Paulo')::date; BEGIN IF NOT private.financeiro_autorizado() THEN RAISE EXCEPTION 'Acesso financeiro não autorizado'; END IF; RETURN jsonb_build_object('hoje',hoje,'residentes',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'nome',nome_completo,'ativo',ativo,'responsavel',responsavel_principal_nome,'telefone',responsavel_principal_telefone) ORDER BY nome_completo),'[]') FROM public.residentes),'cadastros',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.financeiro_cadastros t),'catalogo',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY nome),'[]') FROM public.financeiro_catalogo t),'config',(SELECT to_jsonb(t) FROM public.financeiro_config t WHERE id),'cobrancas',(SELECT coalesce(jsonb_agg(to_jsonb(t)||jsonb_build_object('calculo',private.financeiro_saldo(t.id,hoje)) ORDER BY vencimento),'[]') FROM public.financeiro_cobrancas t),'itens',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.financeiro_itens t),'pagamentos',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY data DESC,criado_em DESC),'[]') FROM public.financeiro_pagamentos t),'alocacoes',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.financeiro_alocacoes t),'contatos',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY criado_em DESC),'[]') FROM public.financeiro_contatos t),'caixa',(SELECT coalesce(jsonb_agg(to_jsonb(t)),'[]') FROM public.financeiro_caixa t),'auditoria',(SELECT coalesce(jsonb_agg(to_jsonb(t) ORDER BY criado_em DESC),'[]') FROM (SELECT * FROM public.financeiro_auditoria ORDER BY criado_em DESC LIMIT 300) t)); END; $$;
REVOKE ALL ON FUNCTION public.financeiro_resumo() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.financeiro_resumo() TO authenticated;
CREATE FUNCTION private.financeiro_gerar_mes(_mes date) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE cfg public.financeiro_config; r record; n integer=0; chave uuid; m date=date_trunc('month',_mes)::date; BEGIN SELECT * INTO cfg FROM public.financeiro_config WHERE id; IF NOT FOUND THEN RETURN 0; END IF; FOR r IN SELECT f.* FROM public.financeiro_cadastros f JOIN public.residentes p ON p.id=f.residente_id WHERE p.ativo AND f.mensalidade_centavos>0 LOOP INSERT INTO public.financeiro_cobrancas(residente_id,tipo,competencia,descricao,valor_centavos,emissao,vencimento,multa_bp,juros_bp,carencia,correcao_bp,criado_por) VALUES(r.residente_id,'mensalidade',m,'Mensalidade '||to_char(m,'MM/YYYY'),r.mensalidade_centavos,m,m+r.dia_vencimento-1,cfg.multa_bp,cfg.juros_bp,cfg.carencia,cfg.correcao_bp,auth.uid()) ON CONFLICT DO NOTHING RETURNING id INTO chave; IF FOUND THEN INSERT INTO public.financeiro_itens(cobranca_id,descricao,categoria,unidade,quantidade,valor_unitario_centavos,total_centavos,data_consumo) VALUES(chave,'Mensalidade','mensalidade','mês',1,r.mensalidade_centavos,r.mensalidade_centavos,m);n=n+1; END IF; END LOOP; RETURN n; END; $$;
REVOKE ALL ON FUNCTION private.financeiro_gerar_mes(date) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.financeiro_operar(_acao text,_dados jsonb,_operacao uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE hoje date=(now() AT TIME ZONE 'America/Sao_Paulo')::date; cfg public.financeiro_config; r record; c public.financeiro_cobrancas; cat public.financeiro_catalogo; s jsonb; id uuid; pid uuid; rid uuid; d date; v bigint; restante bigint; pm bigint; pj bigint; pc bigint; pp bigint; maximo bigint; x jsonb; res jsonb='{}'; chave text; qtd numeric; total bigint; comp date; destino date; motivo text; selecionadas jsonb; BEGIN IF NOT private.financeiro_autorizado() THEN RAISE EXCEPTION 'Acesso financeiro não autorizado'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_operacao::text,0)); SELECT resposta INTO res FROM public.financeiro_operacoes WHERE id=_operacao AND usuario_id=auth.uid() AND acao=_acao; IF FOUND THEN RETURN res; END IF; res='{}'; PERFORM pg_advisory_xact_lock(81722,1); SELECT * INTO cfg FROM public.financeiro_config WHERE id;
IF _acao='config' THEN INSERT INTO public.financeiro_config(id,multa_bp,juros_bp,carencia,correcao_bp,extras_agrupados,extras_dia,alerta_dias,inadimplencia_dias,mensagem,automatico) VALUES(true,(_dados->>'multa_bp')::integer,(_dados->>'juros_bp')::integer,(_dados->>'carencia')::integer,(_dados->>'correcao_bp')::integer,(_dados->>'extras_agrupados')::boolean,nullif(_dados->>'extras_dia','')::integer,(_dados->>'alerta_dias')::integer,(_dados->>'inadimplencia_dias')::integer,_dados->>'mensagem',coalesce((_dados->>'automatico')::boolean,false)) ON CONFLICT(id) DO UPDATE SET multa_bp=excluded.multa_bp,juros_bp=excluded.juros_bp,carencia=excluded.carencia,correcao_bp=excluded.correcao_bp,extras_agrupados=excluded.extras_agrupados,extras_dia=excluded.extras_dia,alerta_dias=excluded.alerta_dias,inadimplencia_dias=excluded.inadimplencia_dias,mensagem=excluded.mensagem,automatico=excluded.automatico,atualizado_em=now();
ELSIF _acao='cadastro' THEN rid=(_dados->>'residente_id')::uuid; IF length(trim(_dados->>'responsavel_nome'))=0 THEN RAISE EXCEPTION 'Informe o responsável financeiro'; END IF; INSERT INTO public.financeiro_cadastros(residente_id,mensalidade_centavos,dia_vencimento,responsavel_nome,responsavel_telefone,forma_preferencial) VALUES(rid,(_dados->>'mensalidade_centavos')::bigint,(_dados->>'dia_vencimento')::integer,_dados->>'responsavel_nome',coalesce(_dados->>'responsavel_telefone',''),_dados->>'forma_preferencial') ON CONFLICT(residente_id) DO UPDATE SET mensalidade_centavos=excluded.mensalidade_centavos,dia_vencimento=excluded.dia_vencimento,responsavel_nome=excluded.responsavel_nome,responsavel_telefone=excluded.responsavel_telefone,forma_preferencial=excluded.forma_preferencial,atualizado_em=now();
ELSIF _acao='catalogo' THEN id=coalesce(nullif(_dados->>'id','')::uuid,gen_random_uuid()); INSERT INTO public.financeiro_catalogo(id,nome,categoria,unidade,valor_centavos,ativo) VALUES(id,trim(_dados->>'nome'),_dados->>'categoria',_dados->>'unidade',(_dados->>'valor_centavos')::bigint,coalesce((_dados->>'ativo')::boolean,true)) ON CONFLICT(id) DO UPDATE SET nome=excluded.nome,categoria=excluded.categoria,unidade=excluded.unidade,valor_centavos=excluded.valor_centavos,ativo=excluded.ativo,atualizado_em=now();res=jsonb_build_object('id',id);
ELSIF _acao='mensalidades' THEN IF cfg.id IS NULL THEN RAISE EXCEPTION 'Salve as configurações financeiras primeiro'; END IF; comp=(_dados->>'mes')::date;PERFORM private.financeiro_travar_data(date_trunc('month',comp)::date); res=jsonb_build_object('geradas',private.financeiro_gerar_mes(comp));
ELSIF _acao='consumo' THEN IF cfg.id IS NULL THEN RAISE EXCEPTION 'Salve as configurações primeiro'; END IF; d=(_dados->>'data')::date;PERFORM private.financeiro_travar_data(d); IF jsonb_array_length(_dados->'residentes')=0 OR jsonb_array_length(_dados->'itens')=0 THEN RAISE EXCEPTION 'Selecione residentes e itens'; END IF; FOR chave IN SELECT jsonb_array_elements_text(_dados->'residentes') LOOP rid=chave::uuid; IF NOT EXISTS(SELECT 1 FROM public.residentes WHERE id=rid AND ativo) THEN RAISE EXCEPTION 'Residente inativa ou inexistente'; END IF; comp=date_trunc('month',d)::date; IF cfg.extras_agrupados THEN SELECT (comp+interval '1 month')::date+coalesce(cfg.extras_dia,f.dia_vencimento)-1 INTO destino FROM public.financeiro_cadastros f WHERE f.residente_id=rid;IF destino IS NULL THEN RAISE EXCEPTION 'Complete o cadastro financeiro da residente'; END IF;SELECT * INTO c FROM public.financeiro_cobrancas WHERE residente_id=rid AND competencia=comp AND tipo='extras' FOR UPDATE; IF FOUND THEN id=c.id;IF c.cancelada OR EXISTS(SELECT 1 FROM public.financeiro_alocacoes WHERE cobranca_id=id) THEN RAISE EXCEPTION 'Extras deste mês já foram pagos ou cancelados. Utilize cobrança avulsa.';END IF; ELSE INSERT INTO public.financeiro_cobrancas(residente_id,tipo,competencia,descricao,emissao,vencimento,multa_bp,juros_bp,carencia,correcao_bp,criado_por) VALUES(rid,'extras',comp,'Extras '||to_char(comp,'MM/YYYY'),d,destino,cfg.multa_bp,cfg.juros_bp,cfg.carencia,cfg.correcao_bp,auth.uid()) RETURNING financeiro_cobrancas.id INTO id; END IF; ELSE destino=(_dados->>'vencimento')::date;INSERT INTO public.financeiro_cobrancas(residente_id,tipo,competencia,descricao,emissao,vencimento,multa_bp,juros_bp,carencia,correcao_bp,criado_por) VALUES(rid,'avulsa',comp,coalesce(nullif(_dados->>'descricao',''),'Consumo de itens'),d,destino,cfg.multa_bp,cfg.juros_bp,cfg.carencia,cfg.correcao_bp,auth.uid()) RETURNING financeiro_cobrancas.id INTO id;END IF; FOR x IN SELECT jsonb_array_elements(_dados->'itens') LOOP SELECT * INTO STRICT cat FROM public.financeiro_catalogo WHERE financeiro_catalogo.id=(x->>'catalogo_id')::uuid AND ativo; qtd=(x->>'quantidade')::numeric;v=(x->>'valor_centavos')::bigint;total=round(qtd*v);INSERT INTO public.financeiro_itens(cobranca_id,catalogo_id,descricao,categoria,unidade,quantidade,valor_unitario_centavos,total_centavos,data_consumo) VALUES(id,cat.id,cat.nome,cat.categoria,cat.unidade,qtd,v,total,d);UPDATE public.financeiro_cobrancas SET valor_centavos=valor_centavos+total WHERE financeiro_cobrancas.id=id;END LOOP;END LOOP;
ELSIF _acao='avulsa' THEN IF cfg.id IS NULL THEN RAISE EXCEPTION 'Salve as configurações primeiro'; END IF;rid=(_dados->>'residente_id')::uuid; d=(_dados->>'data')::date;PERFORM private.financeiro_travar_data(d);v=(_dados->>'valor_centavos')::bigint;IF v<=0 THEN RAISE EXCEPTION 'Valor deve ser positivo';END IF;INSERT INTO public.financeiro_cobrancas(residente_id,tipo,competencia,descricao,valor_centavos,emissao,vencimento,multa_bp,juros_bp,carencia,correcao_bp,observacoes,criado_por) VALUES(rid,'avulsa',date_trunc('month',d)::date,_dados->>'descricao',v,d,(_dados->>'vencimento')::date,cfg.multa_bp,cfg.juros_bp,cfg.carencia,cfg.correcao_bp,coalesce(_dados->>'observacoes',''),auth.uid()) RETURNING financeiro_cobrancas.id INTO id;INSERT INTO public.financeiro_itens(cobranca_id,descricao,categoria,unidade,quantidade,valor_unitario_centavos,total_centavos,data_consumo) VALUES(id,_dados->>'descricao',_dados->>'categoria','un',1,v,v,d);
ELSIF _acao='ajuste' OR _acao='cancelar' OR _acao='perdoar' THEN id=(_dados->>'id')::uuid;SELECT * INTO STRICT c FROM public.financeiro_cobrancas WHERE financeiro_cobrancas.id=id FOR UPDATE;PERFORM private.financeiro_travar_data(hoje);PERFORM private.financeiro_travar_data(c.emissao);motivo=trim(coalesce(_dados->>'motivo',''));IF motivo='' THEN RAISE EXCEPTION 'Informe o motivo';END IF;IF c.cancelada THEN RAISE EXCEPTION 'Cobrança já cancelada';END IF;IF _acao='ajuste' THEN IF EXISTS(SELECT 1 FROM public.financeiro_alocacoes WHERE cobranca_id=id) THEN RAISE EXCEPTION 'Não ajuste uma cobrança com pagamentos';END IF;v=(_dados->>'ajuste_centavos')::bigint;IF c.valor_centavos+v<0 THEN RAISE EXCEPTION 'Desconto excede valor original';END IF;UPDATE public.financeiro_cobrancas SET ajuste_centavos=v,observacoes=observacoes||E'\nAjuste: '||motivo WHERE financeiro_cobrancas.id=id;ELSIF _acao='cancelar' THEN IF EXISTS(SELECT 1 FROM public.financeiro_alocacoes a JOIN public.financeiro_pagamentos p ON p.id=a.pagamento_id WHERE a.cobranca_id=id AND NOT p.estornado) THEN RAISE EXCEPTION 'Estorne os pagamentos antes de cancelar';END IF;UPDATE public.financeiro_cobrancas SET cancelada=true,motivo_cancelamento=motivo WHERE financeiro_cobrancas.id=id;ELSE s=private.financeiro_saldo(id,hoje);INSERT INTO public.financeiro_abatimentos(cobranca_id,data,multa_centavos,juros_centavos,correcao_centavos,motivo,criado_por) VALUES(id,hoje,(s->>'multa')::bigint,(s->>'juros')::bigint,(s->>'correcao')::bigint,motivo,auth.uid());END IF;
ELSIF _acao='pagamento' THEN rid=(_dados->>'residente_id')::uuid;d=(_dados->>'data')::date;v=(_dados->>'valor_centavos')::bigint;IF v<=0 OR d>hoje THEN RAISE EXCEPTION 'Valor ou data do pagamento inválidos';END IF;PERFORM private.financeiro_travar_data(d);PERFORM 1 FROM public.financeiro_cadastros WHERE residente_id=rid FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Complete a ficha financeira';END IF;IF EXISTS(SELECT 1 FROM public.financeiro_pagamentos WHERE residente_id=rid AND NOT estornado AND data>d) THEN RAISE EXCEPTION 'Data anterior a outro pagamento. Estorne e refaça em ordem cronológica.';END IF;selecionadas=_dados->'alocacoes';IF selecionadas IS NOT NULL AND jsonb_array_length(selecionadas)>0 THEN FOR x IN SELECT jsonb_array_elements(selecionadas) LOOP IF NOT EXISTS(SELECT 1 FROM public.financeiro_cobrancas WHERE financeiro_cobrancas.id=(x->>'id')::uuid AND residente_id=rid AND NOT cancelada) THEN RAISE EXCEPTION 'Seleção de cobrança inválida'; END IF;END LOOP;END IF;pid=gen_random_uuid();INSERT INTO public.financeiro_pagamentos(id,residente_id,data,valor_centavos,forma,observacoes,comprovante_path,criado_por) VALUES(pid,rid,d,v,_dados->>'forma',coalesce(_dados->>'observacoes',''),nullif(_dados->>'comprovante_path',''),auth.uid()); restante=v; FOR c IN SELECT * FROM public.financeiro_cobrancas WHERE residente_id=rid AND NOT cancelada ORDER BY vencimento,criado_em FOR UPDATE LOOP s=private.financeiro_saldo(c.id,d);maximo=restante;IF selecionadas IS NOT NULL AND jsonb_array_length(selecionadas)>0 THEN SELECT (z->>'valor')::bigint INTO maximo FROM jsonb_array_elements(selecionadas) z WHERE z->>'id'=c.id::text;IF maximo IS NULL THEN CONTINUE;END IF;IF maximo<0 OR maximo>restante OR maximo>(s->>'saldo')::bigint THEN RAISE EXCEPTION 'Distribuição excede o pagamento ou a dívida';END IF;END IF;maximo=least(maximo,(s->>'saldo')::bigint);IF maximo<=0 THEN CONTINUE;END IF;pm=least(maximo,(s->>'multa')::bigint);maximo=maximo-pm;pj=least(maximo,(s->>'juros')::bigint);maximo=maximo-pj;pc=least(maximo,(s->>'correcao')::bigint);maximo=maximo-pc;pp=least(maximo,(s->>'principal')::bigint);INSERT INTO public.financeiro_alocacoes(pagamento_id,cobranca_id,principal_centavos,multa_centavos,juros_centavos,correcao_centavos) VALUES(pid,c.id,pp,pm,pj,pc);restante=restante-pp-pm-pj-pc;EXIT WHEN restante=0;END LOOP;res=jsonb_build_object('id',pid,'credito',restante);
ELSIF _acao='estornar' THEN id=(_dados->>'id')::uuid;motivo=trim(coalesce(_dados->>'motivo',''));IF motivo='' THEN RAISE EXCEPTION 'Informe o motivo do estorno';END IF;SELECT * INTO STRICT r FROM public.financeiro_pagamentos WHERE financeiro_pagamentos.id=id FOR UPDATE;IF r.estornado THEN RAISE EXCEPTION 'Pagamento já estornado';END IF;PERFORM private.financeiro_travar_data(r.data);PERFORM private.financeiro_travar_data(hoje);IF EXISTS(SELECT 1 FROM public.financeiro_pagamentos WHERE fonte_credito=id AND NOT estornado) THEN RAISE EXCEPTION 'Estorne primeiro os pagamentos que usaram este crédito';END IF;UPDATE public.financeiro_pagamentos SET estornado=true,motivo_estorno=motivo WHERE financeiro_pagamentos.id=id;
ELSIF _acao='contato' THEN INSERT INTO public.financeiro_contatos(cobranca_id,forma,observacao,promessa_data,criado_por) VALUES((_dados->>'id')::uuid,_dados->>'forma',coalesce(_dados->>'observacao',''),nullif(_dados->>'promessa_data','')::date,auth.uid());
ELSIF _acao='caixa' THEN d=(_dados->>'data')::date;IF d>hoje THEN RAISE EXCEPTION 'Não feche data futura';END IF;PERFORM pg_advisory_xact_lock(81721,(d-date '2000-01-01')::integer);motivo=trim(coalesce(_dados->>'motivo',''));IF NOT (_dados->>'fechado')::boolean AND motivo='' THEN RAISE EXCEPTION 'Informe o motivo da reabertura';END IF;INSERT INTO public.financeiro_caixa(data,fechado,motivo,atualizado_por) VALUES(d,(_dados->>'fechado')::boolean,motivo,auth.uid()) ON CONFLICT(data) DO UPDATE SET fechado=excluded.fechado,motivo=excluded.motivo,atualizado_por=excluded.atualizado_por,atualizado_em=now();
ELSE RAISE EXCEPTION 'Operação financeira desconhecida'; END IF;INSERT INTO public.financeiro_operacoes(id,usuario_id,acao,resposta) VALUES(_operacao,auth.uid(),_acao,res);RETURN res;END; $$;
REVOKE ALL ON FUNCTION public.financeiro_operar(text,jsonb,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.financeiro_operar(text,jsonb,uuid) TO authenticated;